import { useState } from "react";

export default function App() {
  const [count, setCount] = useState<number>(0);

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100 p-4">
      <div className="bg-white rounded-xl shadow-md p-8 w-full max-w-sm text-center">
        <h1 className="text-2xl font-semibold mb-6">Contador</h1>

        <div className="flex items-center justify-center gap-6">
          <button
            type="button"
            onClick={() => setCount((c) => c - 1)}
            className="w-12 h-12 rounded-full bg-blue-600 text-white text-2xl hover:bg-blue-700 active:scale-95 transition"
            aria-label="Restar"
          >
            -
          </button>

          <span className="text-4xl font-bold min-w-[3ch] tabular-nums">
            {count}
          </span>

          <button
            type="button"
            onClick={() => setCount((c) => c + 1)}
            className="w-12 h-12 rounded-full bg-blue-600 text-white text-2xl hover:bg-blue-700 active:scale-95 transition"
            aria-label="Sumar"
          >
            +
          </button>
        </div>

        <p className="mt-6 text-gray-700">El doble es {count * 2}</p>

        {count > 5 && (
          <p className="mt-2 text-green-600 font-medium">¡Más de 5!</p>
        )}
      </div>
    </div>
  );
}

