model Todo {
  id: ID
  title: String
  done: Bool
}

component TodoItem(todo: Todo, onDelete: Fn) {
  row gap=2 align=center {
    input todo.done type=checkbox
    text todo.title muted=todo.done
    button "x" small danger -> onDelete(todo.id)
  }
}

page Todos "/" {
  state todos: Todo[] = []
  state draft = ""
  computed pending = todos.filter(t => !t.done).length

  fn add() {
    let title = draft.trim()
    if title == "" { return }
    todos.push({ id: crypto.randomUUID(), title: title, done: false })
    draft = ""
  }

  fn remove(id) {
    todos = todos.filter(t => t.id != id)
  }

  column gap=4 pad=4 {
    title "Tareas"
    row gap=2 align=center {
      input draft placeholder="¿Qué hay que hacer?" -> add()
      button "Agregar" primary -> add()
    }
    column gap=2 {
      for t in todos {
        TodoItem todo=t onDelete=remove
      }
    }
    if todos.length == 0 {
      text "No hay tareas" muted
    } else {
      text `${pending} pendientes` muted
    }
  }
}

