import { useMemo, useState } from "react";

interface User {
  id: number;
  name: string;
  email: string;
}

const INITIAL_USERS: User[] = [
  { id: 1, name: "Lucía Fernández", email: "lucia.fernandez@example.com" },
  { id: 2, name: "Mateo Rodríguez", email: "mateo.rodriguez@example.com" },
  { id: 3, name: "Valentina Gómez", email: "valentina.gomez@example.com" },
  { id: 4, name: "Santiago Pérez", email: "santiago.perez@example.com" },
];

export default function App() {
  const [users] = useState<User[]>(INITIAL_USERS);
  const [query, setQuery] = useState<string>("");

  const filteredUsers = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    if (!normalized) return users;
    return users.filter((user) =>
      user.name.toLowerCase().includes(normalized)
    );
  }, [users, query]);

  return (
    <div className="min-h-screen bg-gray-100 px-4 py-10">
      <div className="mx-auto max-w-2xl">
        <h1 className="mb-6 text-3xl font-bold text-gray-800">Usuarios</h1>

        <input
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Buscar por nombre..."
          className="w-full rounded-lg border border-gray-300 bg-white px-4 py-2 text-gray-800 shadow-sm focus:border-indigo-500 focus:outline-none focus:ring-2 focus:ring-indigo-200"
        />

        <p className="mt-3 text-sm text-gray-600">
          {filteredUsers.length}{" "}
          {filteredUsers.length === 1 ? "resultado" : "resultados"}
        </p>

        <ul className="mt-4 grid gap-4 sm:grid-cols-2">
          {filteredUsers.map((user) => (
            <li
              key={user.id}
              className="rounded-xl bg-white p-4 shadow transition hover:shadow-md"
            >
              <h2 className="text-lg font-semibold text-gray-900">
                {user.name}
              </h2>
              <p className="text-sm text-gray-600">{user.email}</p>
            </li>
          ))}
        </ul>

        {filteredUsers.length === 0 && (
          <p className="mt-6 text-center text-gray-500">
            No se encontraron usuarios.
          </p>
        )}
      </div>
    </div>
  );
}

