model Product {
  id: ID
  name: String
  price: Number
}

model CartItem {
  id: ID
  name: String
  price: Number
  qty: Number
}

page Cart "/" {
  state products: Product[] = [
    { id: "1", name: "Remera", price: 15.5 },
    { id: "2", name: "Pantalón", price: 40 },
    { id: "3", name: "Zapatillas", price: 89.99 }
  ]
  state cart: CartItem[] = []
  computed total = cart.reduce((sum, i) => sum + i.price * i.qty, 0)

  fn addToCart(p) {
    let found = cart.find(i => i.id == p.id)
    if found {
      cart = cart.map(i => i.id == p.id ? { ...i, qty: i.qty + 1 } : i)
    } else {
      cart = [...cart, { id: p.id, name: p.name, price: p.price, qty: 1 }]
    }
  }

  fn changeQty(id, delta) {
    cart = cart
      .map(i => i.id == id ? { ...i, qty: i.qty + delta } : i)
      .filter(i => i.qty > 0)
  }

  column gap=4 pad=4 {
    title "Tienda"
    column gap=2 {
      for p in products {
        card pad=3 {
          row gap=3 align=center justify=between {
            column gap=1 {
              text p.name bold
              text `$${p.price.toFixed(2)}` muted
            }
            button "Agregar" primary -> addToCart(p)
          }
        }
      }
    }
    title "Carrito"
    if cart.length == 0 {
      text "El carrito está vacío" muted
    } else {
      column gap=2 {
        for i in cart {
          card pad=3 {
            row gap=3 align=center justify=between {
              column gap=1 {
                text i.name bold
                text `$${i.price.toFixed(2)} c/u` muted small
              }
              row gap=2 align=center {
                button "-" small -> changeQty(i.id, -1)
                text `${i.qty}`
                button "+" small -> changeQty(i.id, 1)
              }
            }
          }
        }
      }
    }
    text `Total: $${total.toFixed(2)}` bold large
  }
}

model Product {
  id: ID
  name: String
  price: Number
}

model CartItem {
  id: ID
  name: String
  price: Number
  qty: Number
}

component ProductRow(product: Product, onAdd: Fn) {
  card pad=3 {
    row gap=4 align=center justify=between {
      column gap=1 {
        text product.name bold
        text `$${product.price.toFixed(2)}` muted
      }
      button "Agregar" primary -> onAdd(product)
    }
  }
}

component CartRow(item: CartItem, onInc: Fn, onDec: Fn) {
  card pad=3 {
    row gap=4 align=center justify=between {
      column gap=1 {
        text item.name bold
        text `$${item.price.toFixed(2)} c/u` muted small
      }
      row gap=2 align=center {
        button "-" small -> onDec(item.id)
        text `${item.qty}` bold
        button "+" small -> onInc(item.id)
      }
      text `$${(item.price * item.qty).toFixed(2)}`
    }
  }
}

page Cart "/" {
  state products: Product[] = [
    { id: "1", name: "Remera", price: 15.5 },
    { id: "2", name: "Taza", price: 8.25 },
    { id: "3", name: "Mochila", price: 42 }
  ]
  state cart: CartItem[] = []

  computed total = cart.reduce((sum, i) => sum + i.price * i.qty, 0)

  fn addProduct(p) {
    let found = cart.find(i => i.id == p.id)
    if found {
      cart = cart.map(i => i.id == p.id ? { ...i, qty: i.qty + 1 } : i)
    } else {
      cart = [...cart, { id: p.id, name: p.name, price: p.price, qty: 1 }]
    }
  }

  fn inc(id) {
    cart = cart.map(i => i.id == id ? { ...i, qty: i.qty + 1 } : i)
  }

  fn dec(id) {
    cart = cart
      .map(i => i.id == id ? { ...i, qty: i.qty - 1 } : i)
      .filter(i => i.qty > 0)
  }

  column gap=6 pad=6 {
    title "Tienda"
    column gap=2 {
      for p in products {
        ProductRow product=p onAdd=(x => addProduct(x))
      }
    }
    title "Carrito"
    if cart.length == 0 {
      text "El carrito está vacío" muted
    } else {
      column gap=2 {
        for item in cart {
          CartRow item=item onInc=(id => inc(id)) onDec=(id => dec(id))
        }
      }
    }
    text `Total: $${total.toFixed(2)}` bold large
  }
}

