import { useState } from "react";

type Product = {
  id: number;
  nombre: string;
  precio: number;
};

const PRODUCTS: Product[] = [
  { id: 1, nombre: "Auriculares", precio: 49.99 },
  { id: 2, nombre: "Teclado mecánico", precio: 89.5 },
  { id: 3, nombre: "Mouse inalámbrico", precio: 25.9 },
];

export default function App() {
  const [cart, setCart] = useState<Record<number, number>>({});

  const add = (id: number) =>
    setCart((prev) => ({ ...prev, [id]: (prev[id] ?? 0) + 1 }));

  const remove = (id: number) =>
