import { useState, KeyboardEvent } from "react";

type TabId = "perfil" | "ajustes" | "ayuda";

interface Tab {
  id: TabId;
  label: string;
  title: string;
  content: string;
}

const TABS: Tab[] = [
  {
    id: "perfil",
    label: "Perfil",
    title: "Tu perfil",
    content:
      "Acá podés ver y editar tu información personal, como tu nombre, tu foto y tus datos de contacto.",
  },
  {
    id: "ajustes",
    label: "Ajustes",
    title: "Ajustes de la cuenta",
    content:
      "Configurá las notificaciones, la privacidad y las preferencias de la aplicación a tu gusto.",
  },
  {
    id: "ayuda",
    label: "Ayuda",
    title: "Centro de ayuda",
    content:
      "¿Tenés dudas? Consultá las preguntas frecuentes o escribinos y te vamos a responder lo antes posible.",
  },
];

export default function App() {
  const [active, setActive] = useState<TabId>("perfil");
  const current = TABS.find((t) => t.id === active)!;

  const handleKeyDown = (e: KeyboardEvent<HTMLButtonElement>, index: number) => {
    if (e.key === "ArrowRight" || e.key === "ArrowLeft") {
      e.preventDefault();
      const dir = e.key === "ArrowRight" ? 1 : -1;
      const next = (index + dir + TABS.length) % TABS.length;
      setActive(TABS[next].id);
      document.getElementById(`tab-${TABS[next].id}`)?.focus();
    }
  };

  return (
    <div className="min-h-screen bg-slate-100 flex items-center justify-center p-4">
      <div className="w-full max-w-lg bg-white rounded-2xl shadow-lg p-6">
        <h1 className="text-2xl font-bold text-slate-800 mb-4">Mi cuenta</h1>

        <div
          role="tablist"
          aria-label="Secciones"
          className="flex gap-2 border-b border-slate-200 pb-3"
        >
          {TABS.map((tab, i) => {
            const isActive = tab.id === active;
            return (
              <button
                key={tab.id}
                id={`tab-${tab.id}`}
                role="tab"
                type="button"
                aria-selected={isActive}
                aria-controls={`panel-${tab.id}`}
                tabIndex={isActive ? 0 : -1}
                onClick={() => setActive(tab.id)}
                onKeyDown={(e) => handleKeyDown(e, i)}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition focus:outline-none focus-visible:ring-2 focus-visible:ring-indigo-400 ${
                  isActive
                    ? "bg-indigo-600 text-white shadow"
                    : "bg-slate-100 text-slate-600 hover:bg-slate-200"
                }`}
              >
                {tab.label}
              </button>
            );
          })}
        </div>

        <div
          role="tabpanel"
          id={`panel-${current.id}`}
          aria-labelledby={`tab-${current.id}`}
          className="pt-5"
        >
          <h2 className="text-lg font-semibold text-slate-800 mb-2">
            {current.title}
          </h2>
          <p className="text-slate-600 leading-relaxed">{current.content}</p>
        </div>
      </div>
    </div>
  );
}

