import { useState } from "react";

const MIN = 0;
const MAX = 10;

export default function App() {
  const [count, setCount] = useState(0);
  const double = count * 2;

  const decrement = () => setCount((c) => Math.max(MIN, c - 1));
  const increment = () => setCount((c) => Math.min(MAX, c + 1));
  const reset = () => setCount(0);

  return (
    <div className="flex flex-col gap-4 items-center">
      <h2>Contador</h2>
      <div className="flex items-center gap-2">
        <button
          className="disabled:opacity-50 disabled:cursor-not-allowed"
          onClick={decrement}
          disabled={count <= MIN}
        >
          -
        </button>
        <span className="font-semibold">{count}</span>
        <button
          className="primary disabled:opacity-50 disabled:cursor-not-allowed"
          onClick={increment}
          disabled={count >= MAX}
        >
          +
        </button>
      </div>
      <button onClick={reset}>Reset</button>
      <span className="text-gray-500">El doble es {double}</span>
      {count > 5 && <span>¡Más de 5!</span>}
      {count === MAX && <span>Llegaste al máximo ({MAX})</span>}
    </div>
  );
}

