import { useEffect, useState, type FormEvent } from "react";

interface Item {
  id: number;
  name: string;
  bought: boolean;
}

export default function App() {
  const [items, setItems] = useState<Item[]>([]);
  const [name, setName] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  async function load() {
    try {
      const res = await fetch("/api/items");
      if (!res.ok) throw new Error();
      setItems(await res.json());
      setError(null);
    } catch {
      setError("No se pudo conectar con el servidor");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, []);

  async function add(e: FormEvent) {
    e.preventDefault();
    const trimmed = name.trim();
    if (!trimmed) return;
    try {
      const res = await fetch("/api/items", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: trimmed }),
      });
      if (!res.ok) throw new Error();
      const item: Item = await res.json();
      setItems((prev) => [...prev, item]);
      setName("");
      setError(null);
    } catch {
      setError("No se pudo agregar el ítem");
    }
  }

  async function buy(id: number) {
    try {
      const res = await fetch(`/api/items/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ bought: true }),
      });
      if (!res.ok) throw new Error();
      const updated: Item = await res.json();
      setItems((prev) => prev.map((i) => (i.id === id ? updated : i)));
      setError(null);
    } catch {
      setError("No se pudo marcar como comprado");
    }
  }

  async function remove(id: number) {
    try {
      const res = await fetch(`/api/items/${id}`, { method: "DELETE" });
      if (!res.ok && res.status !== 404) throw new Error();
      setItems((prev) => prev.filter((i) => i.id !== id));
      setError(null);
    } catch {
      setError("No se pudo borrar el ítem");
    }
  }

  const pending = items.filter((i) => !i.bought).length;

  return (
    <div className="min-h-screen bg-gray-100 flex justify-center p-6">
      <div className="w-full max-w-md bg-white rounded-xl shadow p-6 h-fit">
        <h1 className="text-2xl font-bold mb-1">Lista de compras</h1>
        <p className="text-gray-600 mb-4">{pending} por comprar</p>

        <form onSubmit={add} className="flex gap-2 mb-4">
          <input
            className="flex-1 border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-400"
            placeholder="Producto"
            value={name}
            onChange={(e) => setName(e.target.value)}
          />
          <button
            type="submit"
            className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
          >
            Agregar
          </button>
        </form>

        {error && (
          <div className="mb-4 text-sm text-red-700 bg-red-100 rounded px-3 py-2">
            {error}
          </div>
        )}

        {loading ? (
          <p className="text-gray-500">Cargando...</p>
        ) : (
          <ul className="space-y-2">
            {items.map((item) => (
              <li
                key={item.id}
                className="flex items-center justify-between border border-gray-200 rounded px-3 py-2"
              >
                <span className={item.bought ? "text-gray-500" : ""}>
                  {item.name}
                  {item.bought && (
                    <span className="ml-2 text-green-600">✓</span>
                  )}
                </span>
                <span className="flex gap-2">
                  {!item.bought && (
                    <button
                      onClick={() => buy(item.id)}
                      className="bg-green-600 text-white text-sm px-3 py-1 rounded hover:bg-green-700"
                    >
                      Comprado
                    </button>
                  )}
                  <button
                    onClick={() => remove(item.id)}
                    className="bg-red-600 text-white text-sm px-3 py-1 rounded hover:bg-red-700"
                  >
                    Borrar
                  </button>
                </span>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

