import http from "node:http";

interface Item {
  id: number;
  name: string;
  bought: boolean;
}

let items: Item[] = [];
let nextId = 1;

function send(res: http.ServerResponse, status: number, body?: unknown) {
  if (body === undefined) {
    res.writeHead(status);
    res.end();
    return;
  }
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(JSON.stringify(body));
}

function readBody(req: http.IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (chunk) => (data += chunk));
    req.on("end", () => {
      if (!data) return resolve({});
      try {
        resolve(JSON.parse(data));
      } catch (e) {
        reject(e);
      }
    });
    req.on("error", reject);
  });
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url ?? "/", "http://localhost");
  const path = url.pathname.replace(/\/+$/, "");
  const method = req.method ?? "GET";

  try {
    if (path === "/api/items") {
      if (method === "GET") return send(res, 200, items);
      if (method === "POST") {
        const body = await readBody(req);
        const name = typeof body.name === "string" ? body.name.trim() : "";
        if (!name) return send(res, 400, { error: "Nombre requerido" });
        const item: Item = { id: nextId++, name, bought: false };
        items.push(item);
        return send(res, 201, item);
      }
      return send(res, 405, { error: "Método no permitido" });
    }

    const match = path.match(/^\/api\/items\/(\d+)$/);
    if (match) {
      const id = Number(match[1]);
      const item = items.find((i) => i.id === id);
      if (!item) return send(res, 404, { error: "No encontrado" });

      if (method === "PATCH") {
        const body = await readBody(req);
        if (typeof body.bought === "boolean") item.bought = body.bought;
        return send(res, 200, item);
      }
      if (method === "DELETE") {
        items = items.filter((i) => i.id !== id);
        return send(res, 204);
      }
      return send(res, 405, { error: "Método no permitido" });
    }

    send(res, 404, { error: "No encontrado" });
  } catch {
    send(res, 400, { error: "Solicitud inválida" });
  }
});

server.listen(Number(process.env.PORT) || 3000, () => {
  console.log("Servidor escuchando");
});

