import { createServer } from "node:http";
import type { IncomingMessage, ServerResponse } from "node:http";

interface Item {
  id: number;
  name: string;
  bought: boolean;
}

let items: Item[] = [];
let nextId = 1;

function send(res: ServerResponse, status: number, body?: unknown) {
  if (body === undefined) {
    res.writeHead(status);
    res.end();
    return;
  }
  res.writeHead(status, { "Content-Type": "application/json; charset=utf-8" });
  res.end(JSON.stringify(body));
}

function readBody(req: IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (chunk) => {
      data += chunk;
      if (data.length > 1e6) {
        reject(new Error("Body too large"));
        req.destroy();
      }
    });
    req.on("end", () => {
      if (!data) return resolve({});
      try {
        resolve(JSON.parse(data));
      } catch (e) {
        reject(e);
      }
    });
    req.on("error", reject);
  });
}

const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url ?? "/", "http://localhost");
    const path = url.pathname.replace(/\/+$/, "") || "/";
    const method = req.method ?? "GET";

    if (!path.startsWith("/api/")) {
      return send(res, 404, { error: "Not found" });
    }

    if (path === "/api/items") {
      if (method === "GET") {
        return send(res, 200, items);
      }
      if (method === "POST") {
        const body = await readBody(req);
        const name = typeof body.name === "string" ? body.name.trim() : "";
        if (!name) return send(res, 400, { error: "Nombre requerido" });
        const item: Item = { id: nextId++, name, bought: false };
        items.push(item);
        return send(res, 201, item);
      }
      return send(res, 405, { error: "Method not allowed" });
    }

    const match = path.match(/^\/api\/items\/(\d+)(\/bought)?$/);
    if (match) {
      const id = Number(match[1]);
      const item = items.find((i) => i.id === id);
      if (!item) return send(res, 404, { error: "Item no encontrado" });

      if (match[2]) {
        if (method === "POST" || method === "PUT" || method === "PATCH") {
          item.bought = true;
          return send(res, 200, item);
        }
        return send(res, 405, { error: "Method not allowed" });
      }

      if (method === "DELETE") {
        items = items.filter((i) => i.id !== id);
        return send(res, 204);
      }
      if (method === "GET") {
        return send(res, 200, item);
      }
      return send(res, 405, { error: "Method not allowed" });
    }

    return send(res, 404, { error: "Not found" });
  } catch (e) {
    return send(res, 400, { error: "Solicitud inválida" });
  }
});

const port = Number(process.env.PORT) || 3000;
server.listen(port, () => {
  console.log(`Servidor escuchando en puerto ${port}`);
});
